// Parse a JS number into decimal coefficient+exponent from its shortest
// round-trip representation (String(v) gives the same digits as Python repr).
export function doubleToDecimal(v) {
  // v must be finite
  const neg = v < 0 || Object.is(v, -0);
  let s = String(Math.abs(v)); // e.g. '123.45', '1e+21', '1.5e-7', '0.000001'
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/.exec(s);
  let digits = m[1] + (m[2] || '');
  let exp = (m[3] ? parseInt(m[3], 10) : 0) - (m[2] || '').length;
  // strip leading zeros
  digits = digits.replace(/^0+(?=\d)/, '');
  return { neg, digits, exp }; // value = digits * 10^exp
}
