```js
export function quantize(dec, q) {
  let { digits, exp } = dec;
  const shift = exp + q;
  let kept, dropped;
  if (shift >= 0) {
    kept = digits + '0'.repeat(shift);
    dropped = '';
  } else {
    const cut = digits.length + shift;
    if (cut > 0) { kept = digits.slice(0, cut); dropped = digits.slice(cut); }
    else { kept = ''; dropped = '0'.repeat(-cut) + digits; }
  }
  if (dropped && shouldRoundUp(kept, dropped)) kept = increment(kept);
  // value = kept * 10^-q
  let padded = kept.padStart(q + 1, '0');
  const intStr = padded.slice(0, padded.length - q) || '0';
  const fracStr = q > 0 ? padded.slice(-q) : '';
  return { intStr, fracStr };
}
```

