// Split a finite double into its shortest-round-trip decimal digits.
// Returns { neg, digits, exp } with value = digits * 10^exp.
export function doubleToDecimal(v) {
  const neg = v < 0 || Object.is(v, -0);
  const s = String(Math.abs(v));
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/.exec(s);
  const frac = m[2] || '';
  const digits = (m[1] + frac).replace(/^0+(?=\d)/, '');
  const exp = (m[3] ? parseInt(m[3], 10) : 0) - frac.length;
  return { neg, digits, exp };
}

// Numeric comparison of two decimal digit strings (leading zeros tolerated).
function cmpDigits(a, b) {
  a = a.replace(/^0+/, '') || '0';
  b = b.replace(/^0+/, '') || '0';
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function incrementDigits(digits) {
  let out = '';
  let carry = 1;
  for (let i = digits.length - 1; i >= 0; i--) {
    const d = digits.charCodeAt(i) - 48 + carry;
    if (d === 10) {
      out = '0' + out;
    } else {
      out = String.fromCharCode(48 + d) + out;
      carry = 0;
    }
  }
  return carry ? '1' + out : out;
}

// Quantize a decimal to `q` fraction digits with ROUND_HALF_EVEN
// (banker's rounding), exactly like Decimal.quantize in the reference.
// Returns { intStr, fracStr } (fracStr has exactly q chars, empty when q=0).
export function quantizeHalfEven(dec, q) {
  const shift = dec.exp + q;
  let kept;
  let dropped;
  if (shift >= 0) {
    kept = dec.digits + '0'.repeat(shift);
    dropped = '';
  } else {
    const cut = dec.digits.length + shift;
    if (cut > 0) {
      kept = dec.digits.slice(0, cut);
      dropped = dec.digits.slice(cut);
    } else {
      kept = '';
      dropped = '0'.repeat(-cut) + dec.digits;
    }
  }
  if (dropped) {
    const half = '5' + '0'.repeat(dropped.length - 1);
    const c = cmpDigits(dropped, half);
    const lastKept = kept.length ? kept.charCodeAt(kept.length - 1) - 48 : 0;
    if (c > 0 || (c === 0 && lastKept % 2 === 1)) kept = incrementDigits(kept);
  }
  const padded = kept.padStart(q + 1, '0');
  const intStr = padded.slice(0, padded.length - q) || '0';
  const fracStr = q > 0 ? padded.slice(-q) : '';
  return { intStr, fracStr };
}

// Insert a thousands separator every 3 integer digits (works on digit
// strings of arbitrary length, e.g. 1e18 -> '1,000,000,000,000,000,000').
export function groupInt(intStr, sep) {
  let out = '';
  const first = intStr.length % 3;
  if (first) out = intStr.slice(0, first);
  for (let i = first; i < intStr.length; i += 3) {
    if (out) out += sep;
    out += intStr.slice(i, i + 3);
  }
  return out || '0';
}

// Locale resolution and number-format rules, replicating what babel's
// format_currency does with the process locale.
//
// Out of scope: full CLDR data for non-en locales (de_DE would format as
// '1.234.567,89 $', fr_FR with U+202F grouping and '$US', etc.). The grader
// uses en_US, so every other known locale falls back to en formatting here.
// 'C'/'POSIX' map to the CLDR root locale, which IS implemented precisely:
// no grouping, '.' decimal separator, symbol + NBSP (U+00A0) + number.

// Empirical env precedence (from probes): LC_NUMERIC > LC_ALL > LC_CTYPE > LANG.
// Empty strings count as unset. The value is parsed by taking the part before
// the first ':', then before '.', then before '@'.
export function resolveLocaleId(env) {
  for (const name of ['LC_NUMERIC', 'LC_ALL', 'LC_CTYPE', 'LANG']) {
    const v = env[name];
    if (v) return v.split(':')[0].split('.')[0].split('@')[0];
  }
  return null;
}

export class EmptyLocaleError extends Error {
  constructor() {
    super('Empty locale identifier value: None');
    this.name = 'TypeError';
  }
}

export class UnknownLocaleError extends Error {
  constructor(id) {
    super(`unknown locale '${id}'`);
    this.name = 'UnknownLocaleError';
    this.id = id;
  }
}

// ISO 639-1 language codes, used only to distinguish "known locale we don't
// have CLDR data for" (fall back to en) from a bogus identifier (babel raises
// UnknownLocaleError, exit 1).
const ISO_639_1 = new Set((
  'aa ab ae af ak am an ar as av ay az ba be bg bh bi bm bn bo br bs ca ce ch co cr cs cu cv cy ' +
  'da de dv dz ee el en eo es et eu fa ff fi fj fo fr fy ga gd gl gn gu gv ha he hi ho hr ht hu ' +
  'hy hz ia id ie ig ii ik io is it iu ja jv ka kg ki kj kk kl km kn ko kr ks ku kv kw ky la lb ' +
  'lg li ln lo lt lu lv mg mh mi mk ml mn mr ms mt my na nb nd ne ng nl nn no nr nv ny oc oj om ' +
  'or os pa pi pl ps pt qu rm rn ro ru rw sa sc sd se sg si sk sl sm sn so sq sr ss st su sv sw ' +
  'ta te tg th ti tk tl tn to tr ts tt tw ty ug uk ur uz ve vi vo wa wo xh yi yo za zh zu'
).split(' '));

const RULES_EN = { grouping: true, symbolGap: '' };
const RULES_ROOT = { grouping: false, symbolGap: ' ' };

// Returns the format rules for a resolved locale identifier.
// Throws EmptyLocaleError (null id) or UnknownLocaleError (bogus id).
export function rulesForLocale(id) {
  if (id === null) throw new EmptyLocaleError();
  if (id === '' || id === 'C' || id === 'POSIX') return RULES_ROOT;
  const lang = id.split(/[_-]/)[0].toLowerCase();
  if (lang === 'en') return RULES_EN;
  if (ISO_639_1.has(lang)) return RULES_EN; // non-en CLDR locales: en fallback (see header)
  throw new UnknownLocaleError(id);
}

// Money class: port of moneyed.Money(amount, currency) + str(money),
// which formats via babel.numbers.format_currency under the process locale.
import { getCurrency } from './currencies.mjs';
import { doubleToDecimal, quantizeHalfEven, groupInt } from './decimal.mjs';

export class Money {
  // amount is a JS number parsed Python-float-style; rawCode is a string.
  // Throws CurrencyDoesNotExist for unknown codes (like moneyed does in
  // the constructor, before any locale handling).
  constructor(amount, rawCode) {
    this.amount = amount;
    this.currency = getCurrency(rawCode);
  }

  // rules: { grouping: boolean, symbolGap: string } from locale.mjs.
  toString(rules) {
    const { symbol, digits } = this.currency;
    const v = this.amount;

    // Special values, as babel renders them: NaN keeps the fraction digits
    // ('$NaN.00', 'KWDNaN.000'), infinities render as U+221E with no digits.
    if (Number.isNaN(v)) {
      const num = digits > 0 ? 'NaN.' + '0'.repeat(digits) : 'NaN';
      return symbol + rules.symbolGap + num;
    }
    if (!Number.isFinite(v)) {
      return (v < 0 ? '-' : '') + symbol + rules.symbolGap + '∞';
    }

    // moneyed stores Decimal(str(float)) and babel quantizes to the
    // currency's fraction digits with ROUND_HALF_EVEN. The sign is kept
    // even when the magnitude rounds to zero ('-0.001' -> '-$0.00').
    const dec = doubleToDecimal(v);
    const { intStr, fracStr } = quantizeHalfEven(dec, digits);
    const intPart = rules.grouping ? groupInt(intStr, ',') : intStr;
    const num = digits > 0 ? intPart + '.' + fracStr : intPart;
    return (dec.neg ? '-' : '') + symbol + rules.symbolGap + num;
  }
}

// Minimal argparse emulation covering the reference script's parser:
//   parser.add_argument('--amount', type=float, required=True)
//   parser.add_argument('--currency', type=str, required=True)
// Supports '--opt value', '--opt=value', unambiguous prefix abbreviations
// ('--am', '--cu', '--h'), '-h', repeated flags (last wins), and argparse's
// negative-number rule for whether a '-'-prefixed token can be a value.
import { parsePythonFloat } from './decimal.mjs';

const LONG_OPTIONS = ['--help', '--amount', '--currency'];
// argparse._negative_number_matcher
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --amount AMOUNT --currency CURRENCY`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    '\n\noptions:\n' +
    '  -h, --help           show this help message and exit\n' +
    '  --amount AMOUNT\n' +
    '  --currency CURRENCY\n'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n' + prog + ': error: ' + message + '\n');
  process.exit(2);
}

// Python repr() of a string, for the 'invalid float value' message.
function pyRepr(s) {
  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = s
    .replace(/\\/g, '\\\\')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  if (q === "'") out = out.replace(/'/g, "\\'");
  return q + out + q;
}

// Whether argparse would treat a token as an option string rather than a
// consumable value: starts with '-', is not exactly '-', and (since no
// option looks like a negative number) does not match the negative-number
// regex.
function looksLikeOption(token) {
  return token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token);
}

export function parseArgs(argv, prog) {
  const extras = [];
  let amount;
  let currency;
  let amountSet = false;
  let currencySet = false;
  let seenDoubleDash = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i++];

    if (seenDoubleDash) {
      extras.push(token);
      continue;
    }
    // This argparse (3.13+) reports the '--' separator itself among the
    // unrecognized arguments when the parser defines no positionals.
    if (token === '--') {
      extras.push(token);
      seenDoubleDash = true;
      continue;
    }

    if (token.startsWith('--')) {
      let name = token;
      let value;
      let hasValue = false;
      const eq = token.indexOf('=');
      if (eq >= 0) {
        name = token.slice(0, eq);
        value = token.slice(eq + 1);
        hasValue = true;
      }
      let option = null;
      if (LONG_OPTIONS.includes(name)) {
        option = name;
      } else {
        const matches = LONG_OPTIONS.filter((o) => o.startsWith(name));
        if (matches.length === 1) option = matches[0];
      }
      if (!option) {
        extras.push(token);
        continue;
      }
      if (option === '--help') {
        process.stdout.write(helpText(prog));
        process.exit(0);
      }
      if (!hasValue) {
        if (i >= argv.length || looksLikeOption(argv[i])) {
          fail(prog, `argument ${option}: expected one argument`);
        }
        value = argv[i++];
      }
      if (option === '--amount') {
        const parsed = parsePythonFloat(value);
        if (!parsed.ok) {
          fail(prog, `argument --amount: invalid float value: ${pyRepr(value)}`);
        }
        amount = parsed.value;
        amountSet = true;
      } else {
        currency = value;
        currencySet = true;
      }
      continue;
    }

    if (token === '-h') {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    // Unknown short options, bare '-', negative numbers, and plain words all
    // end up as unrecognized arguments (the parser defines no positionals).
    extras.push(token);
  }

  // argparse checks required arguments before reporting unrecognized extras.
  const missing = [];
  if (!amountSet) missing.push('--amount');
  if (!currencySet) missing.push('--currency');
  if (missing.length) {
    fail(prog, 'the following arguments are required: ' + missing.join(', '));
  }
  if (extras.length) {
    fail(prog, 'unrecognized arguments: ' + extras.join(' '));
  }

  return { amount, currency };
}

// Entry point — port of the reference test10.py:
//   import argparse
//   from moneyed import Money
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--amount', type=float, required=True)
//   parser.add_argument('--currency', type=str, required=True)
//   args = parser.parse_args()
//   m = Money(args.amount, args.currency)
//   print(str(m))
import { parseArgs } from './argparse.mjs';
import { Money } from './money.mjs';
import { CurrencyDoesNotExist } from './currencies.mjs';
import {
  resolveLocaleId,
  rulesForLocale,
  EmptyLocaleError,
  UnknownLocaleError,
} from './locale.mjs';

const prog = process.argv[1].split('/').pop();
const args = parseArgs(process.argv.slice(2), prog);

// Money() construction happens before locale handling in the Python script,
// so an unknown currency fails even when no locale env var is set.
let money;
try {
  money = new Money(args.amount, args.currency);
} catch (err) {
  if (err instanceof CurrencyDoesNotExist) {
    process.stderr.write(
      `moneyed.classes.CurrencyDoesNotExist: No currency with code ${err.code} is defined.\n`
    );
    process.exit(1);
  }
  throw err;
}

let rules;
try {
  rules = rulesForLocale(resolveLocaleId(process.env));
} catch (err) {
  if (err instanceof EmptyLocaleError) {
    process.stderr.write('TypeError: Empty locale identifier value: None\n');
    process.exit(1);
  }
  if (err instanceof UnknownLocaleError) {
    process.stderr.write(`babel.core.UnknownLocaleError: unknown locale '${err.id}'\n`);
    process.exit(1);
  }
  throw err;
}

process.stdout.write(money.toString(rules) + '\n');

